5	export const WobbleCard = ({
6	  children,
7	  containerClassName,
8	  className,
9	}: {
10	  children: React.ReactNode;
11	  containerClassName?: string;
12	  className?: string;
13	}) => {
14	  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
15	  const [isHovering, setIsHovering] = useState(false);
16	
17	  const handleMouseMove = (event: React.MouseEvent<HTMLElement>) => {
18	    const { clientX, clientY } = event;
19	    const rect = event.currentTarget.getBoundingClientRect();
20	    const x = (clientX - (rect.left + rect.width / 2)) / 20;
21	    const y = (clientY - (rect.top + rect.height / 2)) / 20;
22	    setMousePosition({ x, y });
23	  };
24	  return (
25	    <motion.section
26	      onMouseMove={handleMouseMove}
27	      onMouseEnter={() => setIsHovering(true)}
28	      onMouseLeave={() => {
29	        setIsHovering(false);
30	        setMousePosition({ x: 0, y: 0 });
31	      }}
32	      style={{
33	        transform: isHovering
34	          ? `translate3d(${mousePosition.x}px, ${mousePosition.y}px, 0)`
35	          : "translate3d(0px, 0px, 0)",
36	        transition: "transform 0.1s ease-out",
37	        // this should fix the problem with text blur on translate
38	        backfaceVisibility:"hidden",
39	        WebkitBackfaceVisibility:"hidden"
40	
41	      }}
42	      className={cn(
43	        "mx-auto w-full h-auto border border-blue-1  gap-y-2 items-start  relative rounded-2xl overflow-hidden",
44	        containerClassName
45	      )}
46	    >
47	      <div className="relative  h-full sm:mx-0 sm:rounded-2xl overflow-hidden">
48	        <motion.div
49	          style={{
50	            transform: isHovering
51	              ? `translate3d(${-mousePosition.x}px, ${-mousePosition.y}px, 0)`
52	              : "translate3d(0px, 0px, 0) scale3d(1, 1, 1)",
53	            transition: "transform 0.1s ease-out",
54	          }}
55	          className={cn("h-full px-4 py-20 sm:px-10", className)}
56	        >
57	          {children}
58	        </motion.div>
59	      </div>
60	    </motion.section>
61	  );
62	};
